import {markHintSeen,usedHelp} from './recall-quality.js';
import {battleSequence,reducedEffects} from './cinematic.js';
import {syncCourse,switchLevel} from './learning-level.js';
import {uiIcon,REGIONS,regionFor,mapScene,ambientFX} from './adventure-ui.js';
import {MODES,UNITS,CARDS,TYPES,byId,questions,wordPool} from './data.js';
import {SAVE_KEY,MAX_PROFILES,freshSave,validSave,migrateSave,createProfile,completeMission,reviewWord,dueWords,nextChapter,openPack,revealNext,startBattle,battleAnswer,battleMove,switchCard} from './model.js';
import {storageKey,makeSandboxSave,upgradeSandbox,acceptsBackup} from './sandbox.js';
import {SET_CARDS,isSpecial,finishLabel} from './catalogue.js';
import {COURSES,unitFor,vocabularyFor,migrateCourse,enterUnit,battlePrompt} from './course.js';
import {initRewards,validRewards,acceptsProfileRewards,sparkOf,sparkTier,DISCOVERY,syncDiscovery,equippedLook,equippedTitle} from './rewards.js';
const APP_VERSION='v8.1.0-together-preview · 2026-09-17';
const LAYOUT_KEY='pocket-english-layout';
let layoutChoice='auto';try{const stored=localStorage.getItem(LAYOUT_KEY);if(['auto','vertical','side'].includes(stored))layoutChoice=stored;}catch{}
const TEST_MODE=new URLSearchParams(location.search).get('test')==='1',STORAGE_KEY=storageKey(TEST_MODE);
const newSave=()=>TEST_MODE?makeSandboxSave():freshSave();
const app=document.querySelector('#app'),voice=document.querySelector('#voice');
let save,saveWasMigrated=false;try{const raw=localStorage.getItem(STORAGE_KEY),stored=raw?JSON.parse(raw):null;if(stored){saveWasMigrated=migrateSave(stored);if(validSave(stored)&&acceptsBackup(stored,TEST_MODE)){Object.values(stored.profiles).forEach(initRewards);save=acceptsProfileRewards(stored)?stored:newSave();}else save=newSave();}else save=newSave();}catch{save=newSave();}
const courseWasUpdated=migrateCourse(save);
if(saveWasMigrated||courseWasUpdated){try{localStorage.setItem(STORAGE_KEY,JSON.stringify(save));}catch{}}
if(TEST_MODE&&upgradeSandbox(save)){try{localStorage.setItem(STORAGE_KEY,JSON.stringify(save));}catch{}}
let route=save.active?(save.profiles[save.active].pendingPack?'pack':save.profiles[save.active].route||'home'):'profiles';
let stage=0,selected=[],collectionType='all',collectionLimit=36,detail=null,transition=false,noticeTimer,recording=null,recordStream=null,recordUrl=null,heard=false,speechTried=false,recognition=null;
let mapRegion=null,mapSelected=null,cinematic=null,levelRequest=null;
function runBattleScene(before,move){transition=true;app.querySelectorAll('button, #qa-learning select').forEach(b=>b.disabled=true);cinematic=battleSequence(app,before,structuredClone(profile().battle),move,{effects:save.effects,sound,onEnd(){cinematic=null;transition=false;render();}});}
function cancelBattleScene(){const running=cinematic;cinematic=null;running?.cancel();}
let audioRequest=0,audioText='',audioFailed=false,storageError=false,installPrompt=null;
const profile=()=>save.profiles[save.active];
const trainerName=()=>profile()?.displayName||save.active||'Trainer';
const profileKeys=()=>{const ordered=(save.profileOrder||[]).filter(k=>save.profiles[k]);for(const k of Object.keys(save.profiles))if(!ordered.includes(k))ordered.push(k);return ordered;};
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=uiIcon;
const button=(label,action,cls='',extra='')=>`<button class="${cls}" data-action="${action}" ${extra}>${label}</button>`;
function persist(){Object.values(save.profiles).forEach(p=>{initRewards(p);syncDiscovery(p);});try{localStorage.setItem(STORAGE_KEY,JSON.stringify(save));storageError=false;}catch{storageError=true;notify('저장이 차단되었어요. 설정에서 진행 상황을 내보내 주세요.',true);}}
function notify(text,long=false){const n=document.querySelector('#notice');n.textContent=text;n.classList.add('show');clearTimeout(noticeTimer);noticeTimer=setTimeout(()=>n.classList.remove('show'),long?6500:2800);}
function sound(kind='ok'){if(!save.sound)return;try{const AC=window.AudioContext||window.webkitAudioContext;const ctx=sound.ctx||(sound.ctx=new AC());ctx.resume();const o=ctx.createOscillator(),g=ctx.createGain();o.connect(g);g.connect(ctx.destination);o.type='sine';o.frequency.setValueAtTime(kind==='hit'?170:520,ctx.currentTime);o.frequency.exponentialRampToValueAtTime(kind==='hit'?65:1040,ctx.currentTime+.18);g.gain.setValueAtTime(.055,ctx.currentTime);g.gain.exponentialRampToValueAtTime(.001,ctx.currentTime+.3);o.start();o.stop(ctx.currentTime+.3);}catch{}}
function voiceName(){return 'Molly';}
function hash(text){let h=0;for(let i=0;i<text.length;i++)h=(Math.imul(31,h)+text.charCodeAt(i))>>>0;return h.toString(16);}
async function play(text,slow=false){if(!text)return;const request=++audioRequest;audioText=text;audioFailed=false;voice.pause();voice.src=`./audio/${hash(text)}.mp3`;voice.playbackRate=slow?.75:1;voice.preservesPitch=true;try{await voice.play();if(request!==audioRequest)return;if(route==='lesson'){heard=true;document.querySelector('[data-action="self-check"]')?.removeAttribute('disabled');document.querySelectorAll('.listen .answers button').forEach(b=>b.disabled=false);}document.querySelector('#audio-status')?.replaceChildren(document.createTextNode(slow?'Playing slowly…':'Playing · '+voiceName()));}catch(error){if(request!==audioRequest||error.name==='AbortError')return;audioFailed=true;notify('음성을 재생하지 못했어요. 글로 보기 버튼으로 계속할 수 있어요.',true);if(route==='lesson')render();}}
voice.addEventListener('ended',()=>{document.querySelector('#audio-status')?.replaceChildren(document.createTextNode('NZ English · '+voiceName()));});
function stopMedia(){audioRequest++;voice.pause();recognition?.stop();recognition=null;if(recording?.state==='recording')recording.stop();recordStream?.getTracks().forEach(t=>t.stop());recordStream=null;}
function go(next){cancelBattleScene();if(next==='course'&&route!=='course'){mapRegion=regionFor(profile().chapter);mapSelected=profile().chapter;}stopMedia();transition=false;route=next;detail=null;if(save.active){profile().route=next==='lesson'?'home':next;persist();}render();scrollTo(0,0);}
function art(c,cls=''){return `<div class="art-wrap ${cls}"><img src="${c.art}" alt="${escape(c.name)}" loading="eager" decoding="async"><span class="art-fallback" aria-hidden="true">${TYPES[c.type].symbol}</span></div>`;}
function card(c,small=false,count=0){const sparkN=Math.max(0,count-1),sparkT=sparkTier(sparkN),sparkCls=sparkT!=='none'?' spark-'+sparkT:'',sparkMark=sparkN?`<span class="spark-mark" title="Duplicate Spark ${sparkN}">✦${sparkN}</span>`:'';if(c.cardImage)return `<article class="card printed-card finish-${c.finish} ${isSpecial(c)?'ex':''} ${small?'small':''}${sparkCls}" style="--type:${TYPES[c.type].colour}"><div class="printed-art"><img src="${small?c.thumbnail:c.cardImage}" alt="${escape(c.name)} · ${c.id} · ${escape(c.rarityLabel)}" loading="${small?'lazy':'eager'}" decoding="async"><div class="printed-fallback"><b>${escape(c.name)}</b><span>${c.id} · ${finishLabel(c)}</span><small>카드 그림을 불러올 수 없어요.<br>인터넷 연결 후 다시 열어 주세요.</small></div></div><div class="printed-caption"><b>${escape(c.name)}</b><span>${finishLabel(c)}</span><small>${c.id} · ${c.battleEligible?'POKÉMON':'TRAINER · 수집 카드'}</small></div>${count>1?`<span class="copies">×${count}</span>`:''}${sparkMark}<div class="foil" aria-hidden="true"></div></article>`;return `<article class="card ${c.rarity==='EX'?'ex':''} ${small?'small':''}${sparkCls}" style="--type:${TYPES[c.type].colour}"><div class="card-top"><b>${c.name}</b><small>HP <strong>${c.hp}</strong></small></div><div class="card-art">${art(c)}<span class="type-emblem">${TYPES[c.type].symbol}</span></div><div class="card-bottom"><span>${c.rarity==='EX'?'✦ EX':c.rarity==='rare'?'★ RARE':'◆ BASIC'}</span><span>${TYPES[c.type].symbol} ${c.type}</span></div>${!small?`<div class="card-moves"><b>${c.move}</b><span>25+</span><b>${c.power}</b><span>48+</span></div><p class="card-set">POCKET ADVENTURES · FIRST LIGHT</p>`:''}${count>1?`<span class="copies">×${count}</span>`:''}${sparkMark}<div class="foil" aria-hidden="true"></div></article>`;}
function header(title,sub='',back='home'){return `<header class="topbar">${button(icon('back'),'go:'+back,'icon-button','aria-label="Back"')}<div><p class="eyebrow">${sub}</p><h1>${title}</h1></div>${save.active?`<span class="xp-pill">✦ ${profile().xp} XP</span>`:''}</header>`;}
function nav(active){return `<nav class="bottom-nav" aria-label="Game navigation">${[['home','Home','home'],['course','Map','map'],['missions','Learn','book'],['collection','Cards','cards'],['battle','Battle','battle']].map(([id,label,i])=>button(`${icon(i)}<span>${label}</span>`,id==='battle'?'battle-lobby':'go:'+id,active===id?'active':'',active===id?'aria-current="page"':'')).join('')}</nav>`;}
function lookClass(){return save.active?equippedLook(profile()):'';}
function render(){
 document.body.dataset.layout=layoutChoice;
 app.dataset.route=route;app.className=`app route-${route} ${lookClass()}`.trim();app.dataset.region=save.active?regionFor(profile().chapter):0;
 document.body.className=[...document.body.className.split(/\s+/).filter(c=>c&&!c.startsWith('equip-')),...lookClass().split(/\s+/).filter(Boolean)].join(' ');
 if(!save.active&&route!=='profiles')route='profiles';
 const views={profiles:profilesView,home:homeView,missions:missionsView,lesson:lessonView,summary:summaryView,pack:packView,collection:collectionView,lobby:lobbyView,battle:battleView,settings:settingsView,course:courseView};
 app.innerHTML=(TEST_MODE?sandboxPanel():'')+(views[route]||homeView)();
 app.querySelectorAll('img').forEach(img=>{img.addEventListener('error',()=>img.parentElement.classList.add('missing'));});
 if(transition)app.querySelectorAll('button, #qa-learning select').forEach(b=>b.disabled=true);
 if(route==='course'){const tabs=app.querySelector('.region-tabs'),selectedTab=tabs?.querySelector('.selected');if(selectedTab)tabs.scrollLeft=Math.max(0,selectedTab.offsetLeft-tabs.offsetLeft-tabs.clientWidth/2+selectedTab.clientWidth/2);}
 if(route==='lesson')setTimeout(()=>document.querySelector('#lesson-title')?.focus({preventScroll:true}),0);
}
function sandboxPanel(){return `<aside class="sandbox-panel" aria-label="Parent test controls"><div class="row"><b>부모 테스트 모드</b><a href="./">일반 게임으로 ↗</a></div><p>테스트 전용 저장 · 일반 프로필 기록에 영향 없어요.</p>${save.active?`<form id="qa-learning"><label>학년 <select name="year" aria-label="Test year">${[1,2,3,4,5,6].map(y=>`<option value="${y}" ${profile().learningLevel===y?'selected':''}>Year ${y}</option>`).join('')}</select></label><label>단원 <select name="unit" aria-label="Test unit">${Array.from({length:24},(_,i)=>`<option value="${i}" ${profile().chapter===i?'selected':''}>Unit ${i+1}</option>`).join('')}</select></label><label>학습 <select name="stage" aria-label="Test stage">${MODES.map((m,i)=>`<option value="${i}">${m[0]}</option>`).join('')}</select></label><button type="submit">선택한 학습 바로 실행</button></form><div class="sandbox-actions">${button('팩 바로 뽑기','sandbox-pack')}${button('전투 바로 시작','sandbox-battle')}${button('카드 '+CARDS.length+'종 보기','go:collection')}${route==='battle'&&!profile().battle?.result?button('에너지 3 충전','sandbox-energy'):''}</div>`:'<p>테스트용 프로필을 고르거나 새 프로필을 만들어 체험할 수 있어요.</p>'}</aside>`;}
function profileInitial(name){return [...String(name||'?')][0]?.toLocaleUpperCase()||'?';}
function profilesView(){const keys=profileKeys(),canCreate=keys.length<MAX_PROFILES;return `<main class="profile-screen"><div class="brand"><span class="brand-ball"></span> POKÉMON <span>ENGLISH POCKET</span></div><div class="welcome-art">${ambientFX()}${art(byId(25),'hero-pikachu')}${art(byId(133),'hero-eevee')}<div class="orbit"></div><span class="spark s1">✦</span><span class="spark s2">✧</span></div><p class="eyebrow">A LITTLE ENGLISH. A BIG ADVENTURE.</p><h1>${keys.length?'Who’s exploring today?':'Create your first trainer'}</h1><p class="muted">${keys.length?'Choose a trainer or make a new one.':'이름과 학년을 정하면 이 기기에 진도가 저장돼요.'}</p>${keys.length?`<div class="profile-grid">${keys.map((key,i)=>{const p=save.profiles[key];return button(`<span class="profile-avatar tone-${i%5}">${escape(profileInitial(p.displayName))}<span>✦</span></span><strong>${escape(p.displayName)}</strong><small>Year ${p.learningLevel} · Unit ${p.chapter+1}</small><span class="level-label">${new Set(p.cards).size} cards · ${p.xp} XP</span>`,'profile:'+key,'profile-choice');}).join('')}</div>`:''}${canCreate?`<form id="create-profile-form" class="profile-create"><div><p class="eyebrow">NEW PROFILE · 최대 ${MAX_PROFILES}개</p><h2>${keys.length?'Add another trainer':'Start a new adventure'}</h2></div><label>Trainer name<input id="profile-name" name="name" maxlength="18" autocomplete="off" required placeholder="Name"></label><fieldset><legend>Learning level · 기본 학년</legend><div class="year-picker">${[1,2,3,4,5,6].map((y,i)=>`<label><input type="radio" name="year" value="${y}" ${y===3?'checked':''}><span>Year ${y}</span></label>`).join('')}</div></fieldset><button class="primary" type="submit">Create profile →</button><p class="footnote">각 프로필의 Year 1~6 진도·카드·XP·팩·전투 기록은 이 브라우저에 따로 저장돼요.</p></form>`:`<p class="profile-limit">프로필 5개를 모두 사용 중이에요.</p>`}${installView()}<p class="footnote">NZ everyday English · 학년별 24단원 · 핵심 어휘 각 96개 · 로그인/PIN 없음</p></main>`;}
function homeView(){const p=profile(),u=unitFor(p.learningLevel,p.chapter),done=p.done.length,companion=byId(p.companionId)||byId(25),unique=new Set(p.cards).size,nextGoal=[25,50,100,150,200,250,310].find(n=>n>unique),title=equippedTitle(p);return `<main class="adventure-home ${lookClass()}"><header class="trainer-header"><button class="trainer-badge" data-action="go:profiles" aria-label="Switch trainer"><span class="trainer-portrait">${art(companion)}</span><div><small>YEAR ${u.year} ${title?escape(title).toUpperCase():'EXPLORER'}</small><h1>${escape(trainerName())} <span>Lv. ${1+Math.floor(p.xp/100)}</span></h1></div></button>${button(icon('settings'),'go:settings','icon-button','aria-label="Settings"')}</header><section class="world-hero" aria-label="Your current adventure">${ambientFX()}<div class="world-heading"><span class="chapter-pill">UNIT ${String(p.chapter+1).padStart(2,'0')} / 24 · ${escape(u.place)}</span><h2>${escape(u.name)}</h2></div><div class="companion-stage">${art(companion,'adventure-companion')}<div class="companion-bubble">${done===6?'We did it! Ready for the next adventure?':"Let’s discover something new!"}</div></div><div class="hero-location">${icon('map')} ${REGIONS[regionFor(p.chapter)][0]}</div></section><section class="journey-panel"><div class="row"><div><p class="eyebrow">YOUR ENGLISH POWER</p><h2>${done*10}<span> / 60 XP</span></h2></div><div class="reward-icon">${icon('cards')}<span>${p.packs?'PACK READY':'5-CARD REWARD'}</span></div></div><div class="progress" role="progressbar" aria-label="Current unit progress" aria-valuemin="0" aria-valuemax="6" aria-valuenow="${done}"><i style="width:${done/6*100}%"></i></div>${button(icon('book')+(done===6?'Next unit · 새 단원 →':done?'Continue learning →':'Start adventure →'),'continue','primary')}<div class="home-unit-links">${button(icon('map')+'Adventure map','go:course','text-button')}<span>${done}/6 missions complete</span></div></section><div class="game-tiles">${button(`<span class="tile-art">${icon('cards')}</span><div><strong>Open pack</strong><small>${p.packs?String(p.packs)+' packs ready':'Learn to earn a pack'}</small></div>`,'open-pack','game-tile pack-tile')}${button(`<span class="tile-art">${icon('battle')}</span><div><strong>Battle</strong><small>${p.battle&&!p.battle.result?'Resume battle':'Your team awaits'}</small></div>`,'battle-lobby','game-tile battle-tile')}</div><section class="together-entry"><h2>Together · 친구와 함께</h2><p>실제 사람 1대1 · 4명 2대2 · 2인 보스 레이드 · 던전 · 2인 vs 2 AI 태그</p><a class="outline" href="./multiplayer.html${TEST_MODE?'?test=1':''}">Together 열기 →</a></section><section class="field-notes"><div class="section-heading"><h2>Today’s discoveries</h2><span>4 new words</span></div><div class="word-chips">${u.words.map(w=>'<span>'+escape(w[0])+'</span>').join('')}</div><p>${escape(u.focus)}</p>${nextGoal?`<div class="mini-discovery"><b>${unique} / ${nextGoal}</b><span>Next Pokédex discovery badge</span><i style="width:${Math.min(100,unique/nextGoal*100)}%"></i></div>`:'<div class="mini-discovery complete"><b>310 / 310</b><span>Full collection milestone reached ✦</span></div>'}</section><p class="footnote">${p.xp} total XP · ${unique} card kinds · ${p.wins} wins</p></main>${nav('home')}`;}
function missionsView(){const p=profile();return `<main>${header('English trail','CHAPTER '+(p.chapter+1))}<div class="section-intro"><h2>Small steps.<br><em>Super powers.</em></h2><p class="muted">같은 단어를 듣고, 읽고, 말하며 배워요.</p></div><div class="mission-list">${MODES.map(([name,sub,i],idx)=>button(`<span class="mission-number">${p.done.includes(idx)?'✓':String(idx+1).padStart(2,'0')}</span><div>${icon(i)}<b>${name}</b><small>${sub}</small></div><span class="mission-reward">${p.done.includes(idx)?'Practise':'+10 XP'} →</span>`,'lesson:'+idx,'mission-row '+(p.done.includes(idx)?'complete':''))).join('')}</div>${button(p.done.length===6?'See your reward →':'Continue adventure →',p.done.length===6?'go:summary':'continue','primary')}</main>${nav('missions')}`;}
function lessonState(){const p=profile();if(!p.partial[stage])p.partial[stage]={index:0,words:[],review:dueWords(p).slice(0,2),retry:[],order:null,attempts:0};p.partial[stage].retry||=[];return p.partial[stage];}
function currentQuestion(){const s=lessonState();return questions(profile().learningLevel,profile().chapter,stage,s.review,s.retry)[s.index];}
function lessonView(){const p=profile(),s=lessonState(),qs=questions(profile().learningLevel,p.chapter,stage,s.review,s.retry);if(s.index>=qs.length){s.index=0;}const q=qs[s.index];if(!s.order)s.order=q.options?q.options.map((_,i)=>i).sort(()=>Math.random()-.5):q.words?q.words.map((_,i)=>i).sort(()=>Math.random()-.5):[];
 const practice=p.done.includes(stage);
 return `<main class="lesson-main">${header(MODES[stage][0],`MISSION ${stage+1} OF 6`)}<div class="lesson-progress">${MODES.map((m,i)=>`<i class="${i===stage?'current':p.done.includes(i)?'done':''}"></i>`).join('')}</div><div class="lesson-caption"><span>${practice?'PRACTICE · NO EXTRA XP':'+10 XP WHEN COMPLETE'}</span><span>${s.index+1} / ${qs.length}</span></div><div class="lesson-location">${icon('map')} ${escape(unitFor(profile().learningLevel,p.chapter).name)} <span>YEAR ${unitFor(profile().learningLevel,p.chapter).year}</span></div><section class="lesson-card ${q.kind}"><div class="lesson-symbol">${icon(MODES[stage][2])}</div>${q.story?`<div class="story">${escape(q.story)}</div>${q.glossary?.length?`<details class="context-help"><summary>Word support · 글 속 단어 도움</summary>${q.glossary.map(w=>`<p><b>${escape(w[0])}</b> · ${escape(w[1])}<small>${escape(w[2])}</small></p>`).join('')}</details>`:''}`:''}<p class="eyebrow">${q.kind==='listen'?'EARS READY?':q.kind==='speaking'?'YOUR TURN TO SPEAK':'YOU’VE GOT THIS'}</p><h2 id="lesson-title" tabindex="-1">${escape(q.prompt)}</h2><p class="muted">${q.sub||'Read carefully, then choose. 천천히 읽어 봐요.'}</p>${q.hint?`<details class="meaning-hint" ${q.hintOpen?'open':''}><summary>한국어 힌트</summary><p>${escape(q.hint)}</p></details>`:''}${q.kind==='learn'?`<div class="word-teaching">${q.teach.map((w,i)=>`<article>${button('<b>'+escape(w[0])+'</b>'+icon('sound'),'word-audio:'+i,'word-listen','aria-label="Listen to '+escape(w[0])+'"')}<p>${escape(w[2])}</p><small>${escape(w[1])}</small></article>`).join('')}${button('Ready to try · 뜻을 골라 볼게요 →','learn-ready','primary')}</div>`:''}${q.audio?`<div class="audio-controls">${button(icon('sound')+' Listen','audio','audio-button','aria-label="Listen to the question"')}${button('0.75× Slow','audio-slow','audio-button secondary')}<small id="audio-status">NZ English · ${voiceName()}</small></div>`:''}${q.kind==='listen'?`${button('글로 보기 · Reading fallback','transcript','text-button')}<p id="transcript" class="transcript" ${audioFailed?'':'hidden'}>${audioFailed?escape(q.audio):''}</p>`:''}
 ${q.options?`<div class="answers">${s.order.map((idx,i)=>button(`<span class="answer-letter">${'ABCD'[i]}</span><span>${escape(q.options[idx])}</span>`,'answer:'+idx,'answer',q.kind==='listen'&&!heard?'disabled':'')).join('')}</div>`:''}
 ${q.kind==='sentence'?`<div class="sentence-slot" aria-label="Your sentence">${s.words.length?s.words.map((idx,pos)=>button(escape(q.words[idx]),'unword:'+pos,'word chosen')).join(''):'<span>Tap the words below · 단어를 눌러요</span>'}</div><div class="word-bank">${s.order.map(idx=>button(escape(q.words[idx]),'word:'+idx,'word',s.words.includes(idx)?'disabled':'')).join('')}</div><div class="lesson-actions">${button('Start again','clear-sentence','text-button')}${button('Check sentence →','check-sentence','primary',s.words.length!==q.words.length?'disabled':'')}</div>`:''}
 ${q.kind==='speaking'?speakingPanel():''}</section><p class="lesson-footer">${icon('star')} Mistakes help you learn. Try as often as you like.</p></main>`;
}
function startLesson(i){stage=Math.max(0,Math.min(5,i));heard=false;speechTried=false;if(recordUrl){URL.revokeObjectURL(recordUrl);recordUrl=null;}lessonState();persist();go('lesson');}
function advance(){const p=profile(),s=lessonState(),q=currentQuestion(),assisted=usedHelp(s,q);if(q?.word){reviewWord(p,q.word,true,Date.now(),{assisted});if(assisted&&!q.retry&&!s.retry.includes(q.word))s.retry.push(q.word);}s.index++;s.words=[];s.order=null;s.attempts=0;s.hintSeen=false;heard=false;stopMedia();const qs=questions(profile().learningLevel,p.chapter,stage,s.review,s.retry);
 if(s.index>=qs.length){const earned=completeMission(p,stage);delete p.partial[stage];const next=[0,1,2,3,4,5].find(i=>!p.done.includes(i));if(next===undefined){route='summary';p.route='summary';}else if(!earned){route='missions';p.route='missions';}else{stage=next;lessonState();}notify(earned?'Mission complete! +10 XP ✦':'Nice practice! ✦');}else notify(q.kind==='learn'?'이제 배운 단어의 뜻을 골라 보세요.':'That’s right! 잘했어요 ✦');
 persist();sound();transition=true;render();scrollTo(0,0);setTimeout(()=>{transition=false;render();},650);
}
function wrong(){const s=lessonState(),q=currentQuestion();s.attempts++;if(q.word)reviewWord(profile(),q.word,false);persist();notify(s.attempts>1?`Hint: ${q.options?q.options[q.correct]:q.words.join(' ')}`:'Not quite. Try again! 다시 해봐요.');sound('hit');}
function summaryView(){const p=profile();return `<main class="celebration">${header('Trail complete!','GREAT EXPLORING')}<div class="medal">✦<span>60</span><small>ENGLISH XP</small></div><h2>You did it,<br><em>${escape(trainerName())}!</em></h2><p class="muted">듣고, 읽고, 말하기까지 모두 해냈어요.</p><div class="summary-checks">${MODES.map(([m])=>`<span>✓ ${m}</span>`).join('')}</div>${button(p.packs||p.pendingPack?'Open my reward pack →':'See my collection →',p.packs||p.pendingPack?'open-pack':'go:collection','primary gold')}${button(p.chapter===23?'Finish course · 코스 마무리 →':'Next unit · 새 단원 →','next-chapter','outline')}<p class="footnote">${p.speakingMatches||0} sentence checks · ${p.speakingSelfChecks||0} self-checks<br>같은 단원을 다시 연습하면 XP·팩은 중복 지급되지 않아요.</p><p class="footnote">5 cards · 1 guaranteed EX + 1 special illustration card.</p></main>`;}
function packView(){const p=profile(),pack=p.pendingPack;if(!pack)return `<main>${header('Booster packs','GENETIC APEX · 286 CARDS')}<div class="empty-art">${icon('cards')}</div><h2>${p.packs?'A new friend is waiting.':'Your next pack is close.'}</h2><p class="muted">영어 미션 6개를 마치면 카드 5장을 받아요.<br>매 팩 EX 1장 + 별·왕관 일러스트 1장 보장!</p>${packOdds()}${button(p.packs?'Open pack →':'Go to English trail →',p.packs?'open-pack':'go:missions','primary gold')}</main>${nav('home')}`;
 const c=byId(pack.cards[Math.max(0,pack.index)]),ex=pack.index>=0&&Boolean(c?.isEx||c?.rarity==='EX'),rare=pack.index>=0&&(ex||c?.specialArt),tier=rare?(c.finish||'ex'):'normal',colour=c?.type&&TYPES[c.type]?TYPES[c.type].colour:'#f7cc69',copies=c?p.cards.filter(id=>String(id)===String(c.id)).length:0,spark=c?sparkOf(p.cards,c.id):0,dup=pack.index>=0&&spark>0;return `<main class="pack-room ${rare?'ex-room ex-tier-'+tier:''}${dup?' spark-room spark-'+sparkTier(spark):''} ${lookClass()}" style="--reveal-colour:${colour}">${header('Genetic Apex','286 CARDS · A1')}<div class="pack-heading"><p class="eyebrow">${pack.index<0?'ONE PACK. FIVE NEW POSSIBILITIES.':(pack.index+1)+' / 5 · '+finishLabel(c)}</p><h2>${pack.index<0?'Meet your next teammates.':dup?'Duplicate Spark!':ex?(tier==='crown'?'A legendary pull!':'EX power discovered!'):'A new discovery!'}</h2></div><div class="reveal-stage">${ambientFX('pack-particles')}<div class="pack-aura" aria-hidden="true"></div>${pack.index<0?`<button class="booster" data-action="tear-pack" aria-label="Tear open pack"><div class="crimp"></div><span>POKÉMON</span><small>ENGLISH POCKET</small>${art(byId(25))}<strong>GENETIC APEX</strong><span class="booster-bottom">EX + SPECIAL ART IN EVERY PACK</span><div class="foil"></div></button>`:`<div class="reveal-card" data-key="${pack.index}">${card(c,false,copies)}</div>${dup?`<span class="spark-stamp">DUPLICATE · SPARK ${spark}</span>`:''}${rare?`<div class="ex-radiance" aria-hidden="true"><i></i><i></i><i></i><i></i></div><div class="ex-glitter" aria-hidden="true">${Array.from({length:18},(_,i)=>`<i style="--gx:${7+(i*31)%86}%;--gy:${6+(i*47)%80}%;--delay:${(-i*.11).toFixed(2)}s;--dur:${(1.2+(i%5)*.17).toFixed(2)}s"></i>`).join('')}</div><div class="ex-rays" aria-hidden="true"></div><span class="ex-stamp">${finishLabel(c)}</span>`:''}`}</div><div class="reveal-dots">${pack.cards.map((_,i)=>`<i class="${i<=pack.index?'on':''}"></i>`).join('')}</div>${button(pack.index<0?'Tear open pack ↗':pack.index===4?'Add to collection →':'Reveal next card →',pack.index<0?'tear-pack':'reveal','primary gold')}<p class="footnote">${pack.index<0?'EX 1장 + 특별 일러스트 1장 보장 · 286종':escape(c.name)+(dup?' · DUPLICATE · Spark '+spark+' · 카드는 그대로, 스파크만 커져요':' · Saved to your collection')}</p>${pack.index<0?packOdds():''}</main>`;
}
function packOdds(){return '<details class="pack-odds"><summary>좋은 카드는 얼마나 자주 나오나요?</summary><p>1–3번째: 각 EX 22%, 특별 일러스트 15%.<br>4번째: 별·왕관 카드 보장 (왕관 8%, 3별 12%, 2별 35%, 1별 45%).<br>5번째: EX 보장 (왕관 5%, 3별 10%, 2별 35%, 일반 EX 50%).<br>미보유 카드가 있으면 80% 확률로 우선 선택해요. 한 팩 안의 중복을 피하려고 선택 등급이 소진되면 같은 보장 조건의 다른 카드로 대체해요.</p></details>';}
function discoveryPanel(p){const unique=new Set(p.cards).size,next=DISCOVERY.find(([n])=>n>unique);return `<section class="discovery-panel"><div class="section-heading"><div><p class="eyebrow">DISCOVERY GOALS</p><h2>Pokédex milestones</h2></div><b>${unique} / ${CARDS.length}</b></div><div class="discovery-badges">${DISCOVERY.map(([n,id,name])=>`<span class="${unique>=n?'earned':''}">${unique>=n?'✦':'○'} ${n}<small>${escape(name)}</small></span>`).join('')}</div>${next?`<div class="discovery-progress"><i style="width:${Math.min(100,unique/next[0]*100)}%"></i></div><p>Next: ${escape(next[2])} at ${next[0]} cards · 장식만 해금되며 XP·팩 확률은 그대로예요.</p>`:'<p>All collection milestones discovered! ✦</p>'}</section>`;}
function collectionView(){const p=profile(),unique=[...new Set(p.cards)],owned=unique.map(byId).sort((a,b)=>Number(!!b.set)-Number(!!a.set)||String(a.id).localeCompare(String(b.id))),list=owned.filter(c=>collectionType==='all'||collectionType==='crown'&&c.finish==='crown'||collectionType==='special'&&c.specialArt||collectionType==='ex'&&c.rarity==='EX'||collectionType==='legacy'&&!c.set||collectionType==='A1'&&c.set==='A1'||collectionType==='trainer'&&c.battleEligible===false||c.type===collectionType);const filters=[['all','All cards'],['special','✦ 특별 일러스트'],['ex','EX'],['crown','♛ 왕관'],['A1','A1 · 286종'],['legacy','기존 24종'],['trainer','트레이너'],...Object.entries(TYPES).map(([k,v])=>[k,v.symbol+' '+k])];return `<main class="collection-main ${lookClass()}">${header('Your collection','GENETIC APEX · '+owned.filter(c=>c.set==='A1').length+' / '+SET_CARDS.length)}<div class="collection-stats"><span><b>${unique.length}</b> / ${CARDS.length} kinds</span><span><b>${owned.filter(c=>c.specialArt).length}</b> special art</span><span><b>${Math.max(0,p.cards.length-unique.length)}</b> spark</span></div>${discoveryPanel(p)}<p class="catalogue-note">A1 286종 + 기존 카드 24종 · 같은 포켓몬도 그림·등급별로 모아요.</p><div class="filter-row" role="group" aria-label="Filter cards">${filters.map(([t,label])=>button(label,'filter:'+t,collectionType===t?'selected':'')).join('')}</div><p class="catalogue-note">${list.length}종 · ${Math.min(collectionLimit,list.length)}종 표시</p>${list.length?`<div class="collection-grid">${list.slice(0,collectionLimit).map(c=>`<button class="card-button" data-action="detail:${c.id}" aria-label="View ${escape(c.name)} ${c.id}">${card(c,true,p.cards.filter(id=>String(id)===String(c.id)).length)}</button>`).join('')}</div>${list.length>collectionLimit?button('카드 더 보기 ↓','more-cards','outline'):''}`:`<div class="empty-state"><span>${icon('cards')}</span><h2>${unique.length?'No cards in this filter yet.':'Your story starts with a pack.'}</h2><p class="muted">English missions unlock new Pokémon friends.</p>${button('Start learning →','continue','primary')}</div>`}${detail?`<div class="modal" role="dialog" aria-modal="true" aria-label="Card details"><div class="modal-content">${button('×','close-detail','icon-button modal-close','aria-label="Close card details"')}${card(byId(detail))}<p class="muted">${byId(detail).battleEligible===false?'트레이너 카드 · 도감 수집용':('English adventure · HP '+byId(detail).hp+'<br>'+escape(byId(detail).move)+' · 1 energy / '+escape(byId(detail).power)+' · 3 energy<br>이 게임의 전투 수치는 카드에 인쇄된 TCG 규칙과 달라요.')}${sparkOf(p.cards,detail)?`<br>Duplicate Spark ${sparkOf(p.cards,detail)} · ${sparkTier(sparkOf(p.cards,detail))} · 카드는 삭제되지 않아요.`:''}</p>${button('Back to collection','close-detail','outline')}</div></div>`:''}</main>${nav('collection')}`;}
function lobbyView(){const p=profile(),ids=[...new Set(p.cards)].filter(id=>byId(id).battleEligible!==false);if(ids.length<3)return `<main>${header('Team battle','TRAINING ARENA')}<div class="empty-state">${icon('battle')}<h2>Every trainer needs a team.</h2><p class="muted">Open a pack to find at least 3 different Pokémon.<br>카드를 모으고 나만의 팀을 만들어요.</p>${button(p.packs?'Open my pack →':'Start English missions →',p.packs?'open-pack':'continue','primary')}</div></main>${nav('battle')}`;
 return `<main>${header('Choose your team','TRAINING ARENA')}<p class="muted">Pick 3 friends. Try different types.<br>서로 다른 타입을 섞으면 전투에 도움이 돼요. 트레이너 카드는 수집용이에요.</p><div class="team-slots">${[0,1,2].map(i=>`<div>${selected[i]?art(byId(selected[i])):'<span>+</span>'}<small>${selected[i]?byId(selected[i]).name:'CHOOSE A FRIEND'}</small></div>`).join('')}</div><div class="battle-rules"><span>♪ Answer → +1 energy</span><span>ϟ 1: basic · 3: special</span><span>↔ Switch freely · ◇ shield damage</span></div><div class="collection-grid choose-grid">${ids.map(id=>button(`${card(byId(id),true)}<span class="select-mark">${selected.includes(id)?'✓':'+'}</span>`,'select-card:'+id,'card-button '+(selected.includes(id)?'selected':''),'aria-pressed="'+selected.includes(id)+'" aria-label="Select '+byId(id).name+'"')).join('')}</div><div class="sticky-action">${button(`Enter arena · ${selected.length}/3 →`,'start-battle','primary',selected.length!==3?'disabled':'')}</div></main>`;}
function battleQuestion(){return battlePrompt(profile().learningLevel,profile());}
function battleView(){const p=profile(),b=p.battle;if(!b)return lobbyView();if(b.result)return `<main class="celebration ${lookClass()}">${header(b.result==='won'?'Victory!':'A brave attempt','TRAINING ARENA')}<div class="medal ${b.result==='lost'?'silver':''}">${b.result==='won'?'★':'♡'}</div><h2>${b.result==='won'?'Great words.<br><em>Great teamwork.</em>':'Every try<br><em>makes you stronger.</em>'}</h2><p class="muted">${b.log}</p><div class="winning-team">${b.team.map(t=>art(byId(t.id))).join('')}</div><p class="footnote">${b.turn} English questions · ${b.result==='won'?'+20 XP saved':'Your cards are safe and healed'}</p>${button('Back to adventure →','go:home','primary')}${button('Choose a new team','new-battle','outline')}</main>`;
 const own=byId(b.team[b.active].id),enemy=b.enemies[b.enemy],foe=byId(enemy.id),q=battleQuestion();
 const hp=(name,h,max)=>`<div class="hp-label"><b>${name}</b><span>${h}/${max} HP</span></div><div class="hp-track"><i style="width:${h/max*100}%;${h/max<.3?'background:#ff947d':''}"></i></div>`;
 return `<main class="battle-main ${lookClass()}">${header('Training arena',`OPPONENT ${b.enemy+1} OF 3`)}<section class="arena ${lookClass()}"><div class="arena-grid"></div>${ambientFX()}<div class="battle-vfx" aria-hidden="true"><i></i><i></i><i></i></div><div class="enemy-zone">${hp(foe.name,enemy.hp,enemy.max)}${art(foe,'enemy-mon')}<span class="type-chip">${TYPES[foe.type].symbol} ${foe.type} · weak to ${TYPES[foe.type].weak}</span></div><div class="player-zone">${art(own,'player-mon')}${hp(own.name,b.team[b.active].hp,own.hp)}</div><span class="vs">VS</span><span class="arena-label">FIRST LIGHT LEAGUE</span></section><div class="battle-hud"><div><small>ENGLISH POWER</small><div class="energy">${[1,2,3].map(i=>`<i class="${b.energy>=i?'on':''}">ϟ</i>`).join('')}</div></div><div class="combo">${b.combo} <small>COMBO</small></div><div class="bench">${b.team.map((t,i)=>button(`${art(byId(t.id))}<small>${t.hp} HP</small>`,'switch:'+i,i===b.active?'active':'',t.hp===0?'disabled':'aria-label="Switch to '+byId(t.id).name+'"')).join('')}</div></div><p class="battle-log" role="status">${b.log}</p><section class="battle-console">${b.phase==='question'?`<div class="row"><div><p class="eyebrow">CHARGE YOUR NEXT MOVE</p><h2>${q.word}</h2></div>${button(icon('sound'),'battle-audio','audio-button','aria-label="Listen to battle word"')}</div><div class="answers compact">${q.order.map(i=>button(escape(q.options[i]),'battle-answer:'+i,'answer')).join('')}</div>`:`<p class="eyebrow">CHOOSE YOUR MOVE</p><div class="move-grid">${button(`<b>${own.move}</b><small>ϟ 1 · 25+ damage</small>`,'move:basic','move basic')}${button(`<b>${own.power}</b><small>ϟ 3 · 48+ damage</small>`,'move:special','move special',b.energy<3?'disabled':'')}${button('<b>Charge again</b><small>Answer → more energy</small>','move:charge','move charge',b.energy>=3?'disabled':'')}${button('<b>Protect</b><small>Reduce the next hit by 60%</small>','move:guard','move guard')}</div>`}</section></main>`;
}
function learningSummary(p){const rows=Object.values(p.review||{}),mistakes=new Set(p.mistakes||[]);return {strong:rows.filter(r=>(r.level||0)>=3).length,due:dueWords(p).length,help:rows.filter(r=>(r.stats?.assisted||0)>0).length,independent:rows.reduce((n,r)=>n+(r.stats?.independent||0),0),assisted:rows.reduce((n,r)=>n+(r.stats?.assisted||0),0),misses:rows.reduce((n,r)=>n+(r.stats?.misses||0),0),mistakes:mistakes.size};}
function installView(){const installed=window.matchMedia('(display-mode: standalone)').matches||navigator.standalone===true;return `<section class="install-panel"><h2>앱 설치 · 홈 화면에 추가</h2><p class="muted">${installed?'지금 홈 화면 앱으로 실행 중이에요.':'홈 화면에 게임 아이콘을 추가하면 바로 실행할 수 있어요.'}</p>${installed?'':button('앱 설치 / 홈 화면에 추가','install','primary')}<details id="install-help"><summary>기기별 설치 방법 보기</summary><p><strong>Android · Chrome</strong><br>브라우저 ⋮ 메뉴 → 홈 화면에 추가 → 설치</p><p><strong>iPhone / iPad · Safari</strong><br>공유 버튼 → 홈 화면에 추가 → 추가</p><p><strong>PC · Chrome / Edge</strong><br>주소창의 설치 아이콘 또는 브라우저 메뉴의 앱 설치를 선택하세요.</p><p class="footnote">앱 안의 브라우저에서 설치가 보이지 않으면 이 게임 주소를 Chrome 또는 Safari로 열어 주세요. APK 다운로드나 로그인이 필요 없어요.</p></details></section>`;}
function refreshInstallView(){const panel=app.querySelector('.install-panel');if(panel)panel.outerHTML=installView();}
function settingsView(){const p=profile(),sum=learningSummary(p);return `<main class="settings-main">${header('Trainer settings','YOUR ADVENTURE')}<section class="settings-panel"><h2>게임 버전</h2><p class="muted">${APP_VERSION} · ${TEST_MODE?'부모 테스트 모드':'일반 게임'}<br>${escape(location.hostname)}</p><h2>화면 배치</h2><div class="layout-choices">${[['auto','자동 · 화면 크기에 맞춤'],['vertical','위아래 배치'],['side','좌우 배치']].map(([key,label])=>button(label,'layout:'+key,'outline',`aria-pressed="${layoutChoice===key}"`)).join('')}</div><p class="footnote">홈·전투 화면에 적용하며 이 기기·브라우저에 저장돼요. 좌우 배치도 화면이 아주 좁으면 위아래로 표시해요.</p>${installView()}${!TEST_MODE?'<h2>부모 테스트</h2><p class="muted">모든 카드와 자유로운 팩·전투를 별도 기록으로 체험해요.</p><a class="outline" href="?test=1">부모 테스트 모드 열기 ↗</a>':''}${levelRequest?`<section class="level-confirm" role="group" aria-label="Confirm learning level"><h2>Switch to Year ${levelRequest}?</h2><p>다른 학년의 진도와 카드·XP는 그대로 보존됩니다.</p>${button('Switch to Year '+levelRequest,'confirm-level','primary')}${button('Keep current year','cancel-level','outline')}</section>`:''}<h2>Learning level · ${escape(trainerName())}</h2><p class="muted">Year 1 → Year 2 → Year 3 → Year 4 → Year 5 → Year 6<br>학년을 바꿔도 각 학년의 진도와 카드·XP는 보존돼요.</p><div class="level-choices">${[1,2,3,4,5,6].map(y=>button('Year '+y,'level:'+y,'outline',`aria-pressed="${p.learningLevel===y}"`)).join('')}</div><p class="footnote">${[1,2,3,4,5,6].map(y=>{const c=y===p.learningLevel?p:p.courseProgress['year'+y];return `Year ${y}: Unit ${c.chapter+1} · ${c.done.length}/6`}).join(' / ')}</p><h2>Parent learning snapshot · Year ${p.learningLevel}</h2><div class="learning-snapshot"><div><b>${sum.strong}</b><span>strong words<br>Level 3+</span></div><div><b>${sum.due}</b><span>review due<br>복습 필요</span></div><div><b>${sum.help}</b><span>needed help<br>힌트 경험</span></div></div><p class="footnote">독립 회상 ${sum.independent}회 · 도움 후 정답 ${sum.assisted}회 · 오답 ${sum.misses}회<br>도움을 보고 맞힌 단어는 바로 숙달 처리하지 않고 같은 Vocabulary/Review 세션 뒤쪽에서 다시 확인합니다.</p><h2>Battle effects</h2>${button('Full · 시네마틱','effects:full','outline',`aria-pressed="${!reducedEffects(save.effects)}"`)}${button('Reduced · 움직임 줄이기','effects:reduced','outline',`aria-pressed="${reducedEffects(save.effects)}"`)}<p class="footnote">기본값은 기기의 움직임 줄이기 설정을 따릅니다. Full을 선택하면 타입별 공격·카메라·타격 연출을 사용해요.</p><h2>Sound & voice</h2><p class="muted">AI-generated New Zealand English · ${voiceName()}<br>미리 생성한 음성 파일이라 기기가 달라도 같은 목소리예요.</p><p class="footnote">Molly · New Zealand English</p>${button('♪ Test NZ voice','voice-test','outline')}${button('Game sounds: '+(save.sound?'On':'Off'),'toggle-sound','outline')}<h2>Speaking</h2><p class="muted">주어진 문장을 따라 말하고, 인식되면 다음 문제로 이동합니다. 음소별 발음 점수는 제공하지 않습니다. 지원 여부와 인식 결과는 브라우저·주변 소음에 따라 달라져요.</p><p class="footnote">음성 인식을 켜면 음성이 브라우저 제공업체의 서버에서 처리될 수 있습니다. 게임 서버에는 음성이나 인식 문장을 저장하지 않습니다.</p>${button(save.speechConsent?'자동 음성 인식 끄기':'위 내용을 확인하고 음성 인식 켜기',save.speechConsent?'speech-disable':'speech-enable','outline')}<h2>Your progress</h2><p class="muted">${p.lessonCount} missions · ${p.xp} XP · ${p.cards.length} cards<br>${profileKeys().length}/${MAX_PROFILES} profiles · 이 브라우저에 각각 저장돼요.</p>${storageError?'<p class="error">Storage unavailable. Export progress before closing.</p>':''}${button('Export progress · 백업 저장','export','outline')}<label class="file-button">Restore progress · 백업 불러오기<input type="file" id="import-save" accept="application/json,.json"></label><p class="footnote">불러오면 이 브라우저의 전체 프로필 진행 상황을 백업으로 교체합니다. 기존 v6 Tony/Kai 백업도 자동 이전합니다.</p>${button('Switch trainer','go:profiles','outline')}<p class="footnote">Private family fan game. Pokémon names and artwork belong to their respective owners. Card images are loaded from TCGdex; battle artwork is loaded from the PokeAPI community sprite repository. This is an independent game, not the official Pokémon TCG rules.</p></section></main>`;}
async function record(){if(recording?.state==='recording'){recording.stop();return;}
 if(!navigator.mediaDevices?.getUserMedia){notify('이 브라우저는 녹음을 지원하지 않아요. 소리 내어 읽고 자기 확인으로 계속하세요.',true);return;}
 try{stopMedia();recordStream=await navigator.mediaDevices.getUserMedia({audio:true});if(route!=='lesson'){recordStream.getTracks().forEach(t=>t.stop());return;}const parts=[];recording=new MediaRecorder(recordStream);recording.ondataavailable=e=>{if(e.data.size)parts.push(e.data);};recording.onstop=()=>{recordStream?.getTracks().forEach(t=>t.stop());if(recordUrl)URL.revokeObjectURL(recordUrl);recordUrl=URL.createObjectURL(new Blob(parts,{type:recording.mimeType}));if(route==='lesson'){document.querySelector('[data-action="play-recording"]')?.removeAttribute('disabled');const btn=document.querySelector('[data-action="record"]');if(btn)btn.textContent='Record again';document.querySelector('#record-status')?.replaceChildren(document.createTextNode('Recording ready. Listen and compare!'));}};recording.start();document.querySelector('[data-action="record"]').textContent='■ Stop recording';document.querySelector('#record-status').textContent='Recording… up to 10 seconds';setTimeout(()=>{if(recording?.state==='recording')recording.stop();},10000);}catch{notify('마이크를 사용할 수 없어요. 듣고 따라 말한 뒤 자기 확인으로 계속하세요.',true);}}
// Capture opening before the native details toggle; closing never clears exposure.
app.addEventListener('click',e=>{
 const summary=e.target.closest('.meaning-hint > summary');
 if(route==='lesson'&&summary&&!summary.parentElement.open&&markHintSeen(lessonState(),currentQuestion()))persist();
},true);
app.addEventListener('submit',e=>{if(TEST_MODE&&e.target.id==='qa-learning'){e.preventDefault();if(transition)return;const d=new FormData(e.target);cancelBattleScene();stopMedia();switchLevel(profile(),Number(d.get('year')));enterUnit(profile(),Number(d.get('unit')),{sandbox:true});persist();startLesson(Number(d.get('stage')));return;}if(e.target.id!=='create-profile-form')return;e.preventDefault();const data=new FormData(e.target),result=createProfile(save,data.get('name'),data.get('year'));if(!result.ok){notify(result.error,true);return;}if(TEST_MODE){upgradeSandbox(save);result.profile.packs=10;}route='home';persist();render();scrollTo(0,0);sound();notify('Profile created · 이 기기에 저장됐어요.');});
app.addEventListener('click',async e=>{const b=e.target.closest('button[data-action]');if(!b||b.disabled||transition)return;const [action,value]=b.dataset.action.split(':');
 if(action==='install'){if(installPrompt){const pending=installPrompt;installPrompt=null;try{await pending.prompt();await pending.userChoice;}catch{notify('브라우저 메뉴에서 홈 화면에 추가를 선택해 주세요.',true);}refreshInstallView();}else{const help=app.querySelector('#install-help');if(help){help.open=true;help.scrollIntoView({block:'nearest'});}}return;}
 if(action==='profile'){save.active=value;route=profile().pendingPack?'pack':'home';persist();render();sound();return;}
 if(action==='go'){go(value);return;}
 if(!save.active)return;
 const p=profile();
 if(TEST_MODE&&action==='sandbox-pack'){p.packs=Math.max(10,p.packs);openPack(p);persist();go('pack');}
 if(TEST_MODE&&action==='sandbox-battle'){p.battle=null;startBattle(p,['A1-284','A1-285','A1-286']);persist();go('battle');}
 if(TEST_MODE&&action==='sandbox-energy'&&p.battle&&!p.battle.result){p.battle.energy=3;p.battle.phase='move';p.battle.log='Test mode: special moves are ready.';persist();render();}
 if(action==='continue'){const next=[0,1,2,3,4,5].find(i=>!p.done.includes(i));if(next===undefined){nextChapter(p);persist();go(p.route);}else startLesson(next);}
 if(action==='lesson')startLesson(Number(value));
 if(action==='audio'||action==='audio-slow')play(currentQuestion().audio,action==='audio-slow');
 if(action==='transcript'){heard=true;document.querySelectorAll('.listen .answers button').forEach(b=>b.disabled=false);const t=document.querySelector('#transcript');t.hidden=false;t.textContent=currentQuestion().audio+' · 글로 읽고 푸는 연습이에요.';}
 if(action==='answer'){if(currentQuestion().kind==='listen'&&!heard)return;if(Number(value)===currentQuestion().correct)advance();else{b.classList.add('wrong');wrong();}}
 if(action==='word'){const s=lessonState();if(!s.words.includes(Number(value)))s.words.push(Number(value));persist();render();}
 if(action==='unword'){lessonState().words.splice(Number(value),1);persist();render();}
 if(action==='clear-sentence'){lessonState().words=[];persist();render();}
 if(action==='check-sentence'){const q=currentQuestion(),s=lessonState();s.words.map(i=>q.words[i]).join(' ')===q.words.join(' ')?advance():wrong();}
 if(action==='record')record();
 if(action==='play-recording'&&recordUrl){voice.pause();voice.src=recordUrl;voice.playbackRate=1;voice.play().catch(()=>notify('Try recording again.'));}
 if(action==='speech-fallback'){stopMedia();heard=true;document.querySelector('[data-action="self-check"]')?.removeAttribute('disabled');document.querySelector('#record-status').textContent='글을 소리 내어 읽고 자기 확인을 눌러요. 듣기·발음 채점 없이 진행합니다.';}
 if(action==='self-check'&&heard){p.speakingSelfChecks=(p.speakingSelfChecks||0)+1;advance();}
 if(action==='next-chapter'){if(nextChapter(p)){persist();go(p.route);}}
 if(action==='map-region'){mapRegion=Number(value);mapSelected=mapRegion*4;render();}
 if(action==='map-select'){mapSelected=Number(value);render();}
 if(action==='map-jump'){mapSelected=Number(value);mapRegion=regionFor(mapSelected);render();scrollTo(0,0);}
 if(action==='enter-unit'){if(enterUnit(p,Number(value),{sandbox:TEST_MODE})){persist();go('home');}}
 if(action==='word-audio'){const w=unitFor(profile().learningLevel,p.chapter).words[Number(value)];if(w)play(w[0]);}
 if(action==='learn-ready')advance();
 if(action==='speech-enable'){save.speechConsent=true;persist();render();}
 if(action==='speech-disable'){stopMedia();save.speechConsent=false;persist();render();}
 if(action==='speak-now')startAutoSpeaking();
 if(action==='speak-stop'){stopMedia();render();}
 if(action==='open-pack'){openPack(p);persist();go('pack');}
 if(action==='tear-pack'){if(!p.pendingPack||p.pendingPack.index!==-1)return;transition=true;app.querySelector('.booster')?.classList.add('tearing');sound();setTimeout(()=>{revealNext(p);persist();transition=false;render();},600);}
 if(action==='reveal'){transition=true;const more=revealNext(p);persist();sound();if(!more){route='collection';p.route='collection';persist();}render();if(p.pendingPack?.index===4){navigator.vibrate?.([50,30,80]);sound();}setTimeout(()=>{transition=false;render();},400);}
 if(action==='filter'){collectionType=value;collectionLimit=36;render();}
 if(action==='more-cards'){collectionLimit+=36;const y=scrollY;render();scrollTo(0,y);}
 if(action==='detail'){detail=byId(value)?.id;render();document.querySelector('.modal-close')?.focus();}
 if(action==='close-detail'){detail=null;render();}
 if(action==='battle-lobby'){if(p.battle&&!p.battle.result)go('battle');else{selected=[];go('lobby');}}
 if(action==='select-card'){const id=byId(value)?.id;selected=selected.includes(id)?selected.filter(x=>x!==id):selected.length<3?[...selected,id]:selected;const y=scrollY;render();scrollTo(0,y);}
 if(action==='start-battle'){if(startBattle(p,selected)){persist();go('battle');}}
 if(action==='new-battle'){p.battle=null;selected=[];persist();go('lobby');}
 if(action==='battle-audio')play(battleQuestion().word);
 if(action==='battle-answer'){const before=structuredClone(p.battle),q=battleQuestion(),ok=Number(value)===0;if(!battleAnswer(p,ok))return;reviewWord(p,q.word,ok);persist();sound(ok?'ok':'hit');if(ok)render();else runBattleScene(before,'miss');}
 if(action==='move'){const before=structuredClone(p.battle),c=byId(before.team[before.active].id);if(battleMove(p,value)){persist();if(value==='charge'){sound();render();}else{if(['basic','special'].includes(value))play(value==='special'?c.power:c.move);runBattleScene(before,value);}}}
 if(action==='switch'){const before=structuredClone(p.battle);if(switchCard(p,Number(value))){persist();runBattleScene(before,'switch');}}
 if(action==='voice-test')play('Kia ora, trainer! Let us go on an adventure.');
 if(action==='level'){if(Number(value)!==p.learningLevel){levelRequest=Number(value);go('settings');}}
 if(action==='cancel-level'){levelRequest=null;render();}
 if(action==='confirm-level'&&levelRequest){stopMedia();switchLevel(p,levelRequest);levelRequest=null;mapRegion=null;mapSelected=null;persist();go('home');}
 if(action==='layout'&&['auto','vertical','side'].includes(value)){layoutChoice=value;try{localStorage.setItem(LAYOUT_KEY,value);}catch{notify('배치 설정을 저장할 수 없어요.',true);}render();return;}
 if(action==='effects'){save.effects=value;persist();render();}
 if(action==='toggle-sound'){save.sound=!save.sound;persist();render();}
 if(action==='export'){persist();const blob=new Blob([JSON.stringify(save,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=TEST_MODE?'pocket-test-progress-v7.json':'pocket-english-progress-v7.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notify('Progress exported. 백업 파일을 보관해 주세요.');}

});
app.addEventListener('change',async e=>{if(e.target.id!=='import-save')return;try{const text=await e.target.files[0].text();if(text.length>2e6)throw Error();const data=JSON.parse(text);migrateSave(data);if(!validSave(data)||!acceptsBackup(data,TEST_MODE)||!acceptsProfileRewards(data))throw Error();if(!confirm('Replace all local profiles with this backup? 현재 전체 진행 상황을 교체할까요?'))return;save=data;migrateCourse(save);Object.values(save.profiles).forEach(initRewards);if(TEST_MODE)upgradeSandbox(save);persist();go(save.active?'home':'profiles');notify('Progress restored.');}catch{notify('올바른 Pocket English 백업 파일이 아니에요.',true);}});
app.addEventListener('pointermove',e=>{if(e.pointerType!=='mouse')return;const card=e.target.closest('.card');if(card){const r=card.getBoundingClientRect();card.style.transform=`perspective(700px) rotateY(${(e.clientX-r.x-r.width/2)/r.width*12}deg) rotateX(${-(e.clientY-r.y-r.height/2)/r.height*10}deg)`;}});
app.addEventListener('pointerout',e=>{const card=e.target.closest('.card');if(card)card.style.transform='';});
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;refreshInstallView();});
window.addEventListener('appinstalled',()=>{installPrompt=null;refreshInstallView();notify('설치 완료! 홈 화면 아이콘으로 실행하세요.');});
window.addEventListener('keydown',e=>{if(e.key==='Escape'&&detail){detail=null;render();}});
window.addEventListener('pagehide',cancelBattleScene);
document.addEventListener('visibilitychange',()=>{if(document.hidden)cancelBattleScene();});
window.addEventListener('storage',e=>{cancelBattleScene();if(e.key===STORAGE_KEY){try{const data=JSON.parse(e.newValue);migrateSave(data);if(validSave(data)){stopMedia();save=data;migrateCourse(save);if(TEST_MODE)upgradeSandbox(save);route=save.active?'home':'profiles';render();notify('다른 탭에서 진행 상황이 업데이트되었어요.');}}catch{}}});
document.addEventListener('visibilitychange',()=>{if(document.hidden)stopMedia();});
window.addEventListener('pagehide',stopMedia);
if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});
try{document.modelContext?.registerTool({name:'read_trainer_progress',description:'Read the selected trainer’s local learning and collection progress.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>save.active?{trainer:trainerName(),xp:profile().xp,chapter:profile().chapter+1,missions:profile().done.length,cards:profile().cards.length}: {trainer:null}});}catch{}
render();

function speakingPanel(){const supported=!!(window.SpeechRecognition||window.webkitSpeechRecognition);return `<div class="speech-guide"><span>1. Listen</span><span>2. Speak</span><span>3. Auto check</span></div><div class="lesson-actions">${!supported?'<p class="muted">이 브라우저에서는 자동 음성 인식을 사용할 수 없어요. 아래 자기 확인으로 연습하세요.</p>':!save.speechConsent?`<p class="muted">말한 문장을 인식하면 자동으로 확인돼요.</p><p class="footnote">음성은 저장하지 않아요. 보호자와 확인한 뒤 사용하세요.</p>${button('확인했어요 · 음성 인식 켜기','speech-enable','primary')}`:`<p id="speech-transcript" class="speech-transcript" aria-live="polite"></p>${button('🎙 Speak now · 말하기 시작','speak-now','primary')}${button('Stop listening · 인식 중지','speak-stop','text-button')}`}<p id="record-status" role="status" class="muted">${supported&&save.speechConsent?'버튼을 누르고 문장을 말하면 자동으로 확인해요.':'먼저 문장을 듣고 소리 내어 연습해요.'}</p><p class="footnote">문장 인식 확인 · 정밀 발음 점수가 아니에요.</p>${button('음성 인식 없이 소리 내어 연습하기','speech-fallback','text-button')}${button('소리 내어 읽었어요 · 자기 확인','self-check','outline',heard?'':'disabled')}</div>`;}
function startAutoSpeaking(){if(route!=='lesson'||currentQuestion().kind!=='speaking'||!save.speechConsent)return;const Recognition=window.SpeechRecognition||window.webkitSpeechRecognition;if(!Recognition){document.querySelector('#record-status')?.replaceChildren(document.createTextNode('음성 인식이 잘 안 됐어요. 문장을 소리 내어 말했다면 직접 확인할 수 있어요.'));return;}stopMedia();const expected=currentQuestion().prompt,trainer=save.active,at=lessonState().index;let controller;const current=()=>route==='lesson'&&save.active===trainer&&stage===4&&lessonState().index===at;const status=(code,text)=>{if(!current())return;const messages={listening:'듣고 있어요… 문장을 말해 주세요.', 'not-allowed':'마이크 사용이 허용되지 않았어요. 아래 자기 확인을 사용할 수 있어요.','service-not-allowed':'이 브라우저에서 음성 인식을 사용할 수 없어요.','no-speech':'음성 인식이 잘 안 됐어요. 다시 말하거나 자기 확인을 사용하세요.',network:'음성 인식 연결에 실패했어요. 다시 말하거나 자기 확인을 사용하세요.',timeout:'음성 인식이 잘 안 됐어요. 다시 말하거나 자기 확인을 사용하세요.',unavailable:'음성 인식을 시작할 수 없어요. 자기 확인으로 연습할 수 있어요.'};const transcript=document.querySelector('#speech-transcript');if(text)transcript?.replaceChildren(document.createTextNode('인식한 문장: “'+text+'”'));document.querySelector('#record-status')?.replaceChildren(document.createTextNode(code==='mismatch'?'거의 맞았어요. 한 번 더 말해볼까요?':messages[code]||'인식하지 못했어요. 다시 시도해 주세요.'));};const end=()=>{if(recognition===controller)recognition=null;if(current())document.querySelector('[data-action="speak-now"]')?.removeAttribute('disabled');};document.querySelector('[data-action="speak-now"]')?.setAttribute('disabled','');status('listening','');controller=startSentenceRecognition({Recognition,expected,onStatus:status,onMatch:heardText=>{if(!current())return;document.querySelector('#speech-transcript')?.replaceChildren(document.createTextNode('인식한 문장: “'+heardText+'”'));document.querySelector('#record-status')?.replaceChildren(document.createTextNode('✅ 잘했어요!'));profile().speakingMatches=(profile().speakingMatches||0)+1;recognition=null;setTimeout(advance,700);},onEnd:end});recognition=controller;}
function courseView(){const p=profile(),units=COURSES[profile().learningLevel];if(mapRegion===null)mapRegion=regionFor(p.chapter);if(mapSelected===null||regionFor(mapSelected)!==mapRegion)mapSelected=mapRegion===regionFor(p.chapter)?p.chapter:mapRegion*4;const completed=i=>(i===p.chapter?p.done:p.unitProgress?.[i]?.done)?.length===6;const i=mapSelected,u=units[i],available=TEST_MODE||i===0||i===p.chapter||completed(i)||completed(i-1),count=units.filter((_,n)=>completed(n)).length;return `<main class="map-main">${header('Adventure map','NZ ENGLISH · YEAR '+u.year)}<div class="map-progress"><b>${count} / 24</b><span>units explored · 핵심 어휘 96개</span></div><div class="region-tabs" role="group" aria-label="Choose map region">${REGIONS.map((r,n)=>button(`<small>${String(n+1).padStart(2,'0')}</small>${r[0]}`,'map-region:'+n,n===mapRegion?'selected':'',`aria-pressed="${n===mapRegion}"`)).join('')}</div>${mapScene(units,p,mapRegion,mapSelected,TEST_MODE)}<section class="map-unit-detail" aria-live="polite"><div class="row"><p class="eyebrow">UNIT ${String(i+1).padStart(2,'0')} · ${completed(i)?'COMPLETE':i===p.chapter?'CURRENT ADVENTURE':available?'READY TO EXPLORE':'LOCKED'}</p>${completed(i)?icon('check'):icon('book')}</div><h2>${escape(u.name)}</h2><p>${escape(u.focus)}</p><div class="word-chips">${u.words.map(w=>'<span>'+escape(w[0])+'</span>').join('')}</div>${button(available?(completed(i)?'Practise again →':'Explore this unit →'):'먼저 앞 단원을 완료해 주세요','enter-unit:'+i,'primary',available?'':'disabled')}</section>${p.courseComplete?'<div class="course-complete">24단원 완주! 배운 영어를 생활 속에서 사용해 보세요.</div>'+ (p.learningLevel<6?button('Ready for Year '+(p.learningLevel+1)+' →','level:'+(p.learningLevel+1),'primary'):''):''}<details class="course-directory"><summary>All 24 units · 전체 단원 보기</summary><div class="course-list">${units.map((unit,n)=>button(`<span class="unit-number">${completed(n)?'✓':n+1}</span><div><b>${escape(unit.name)}</b><small>${unit.words.map(w=>escape(w[0])).join(' · ')}</small></div>`,'map-jump:'+n,'course-unit '+(n===p.chapter?'current':''))).join('')}</div></details><p class="footnote">${TEST_MODE?'부모 테스트에서는 모든 단원을 열 수 있어요.':'단원을 마치면 다음 단원이 열려요. 복습은 보상을 중복 지급하지 않아요.'}<br>학교 영어를 보충하는 NZ 생활영어 코스입니다.</p></main>${nav('course')}`;}
